import AppState from'../core/app-state.js';import DOMElements from'../core/dom-elements.js';import Utils from'../core/utils.js';import API from'../api/api-client.js';import InteractiveACLBuilder from'./interactive-acl-builder.js';const CommandTester={async testCommand(){const command=DOMElements.testCommandInput.value.trim();const rule=InteractiveACLBuilder.getLastValidRule();if(!command){const html=`
                <strong>❌ Error</strong><br>
                Please enter a command to test!
            `;Utils.showDismissibleTestResult(DOMElements.testResult,html,'denied',5000);DOMElements.testCommandInput.focus();return;}
if(!rule){const html=`
                <strong>❌ No Valid Rule</strong><br>
                Please create or submit an ACL rule first before testing commands.
            `;Utils.showDismissibleTestResult(DOMElements.testResult,html,'denied',5000);return;}
if(AppState.isLoading)return;Utils.showLoading(DOMElements.testResult);try{const data=await API.testCommand(rule,command,AppState.currentVersion,AppState.currentMode);this.displayTestResult(data);}catch(error){let errorMessage=error.message;if(errorMessage.includes('not found in REDIS')){const commandMatch=errorMessage.match(/Command '([^']+)'/);const versionMatch=errorMessage.match(/REDIS(\d+)/);const commandName=commandMatch?commandMatch[1]:'command';const version=versionMatch?versionMatch[1]:'8';errorMessage=`❌ Command '${commandName}' not found in Redis ${version}. Please check the command spelling.`;}else{errorMessage=`Error testing command: ${errorMessage}`;}
Utils.showDismissibleTestResult(DOMElements.testResult,errorMessage,'denied',5000);}finally{Utils.hideLoading(DOMElements.testResult);}},displayTestResult(data){const resultClass=data.is_granted?'granted':'denied';const statusIcon=data.is_granted?'✅':'❌';let html=`
            <strong>${statusIcon} Command: ${Utils.escapeHtml(data.command).toLowerCase()} -> ${Utils.escapeHtml(data.explanation)}</strong><br>
        `;if(data.categories&&data.categories.length>0){const categoriesHtml=data.categories.map(cat=>`<span class="category-tag" title="Category: ${Utils.escapeHtml(cat)}">${Utils.escapeHtml(cat)}</span>`).join('');html+=`
                <div class="command-categories">
                    <strong>Categories:</strong>
                    ${categoriesHtml}
                </div>
            `;}
Utils.showDismissibleTestResult(DOMElements.testResult,html,resultClass,5000);}};export default CommandTester;